#include <cstdio>
#include <vector>
#include <map>
using namespace std;

typedef vector<int> vi;

struct SegTree {
    vi data;
    int size;

    SegTree(int _size) : size(1) {
        while (size < _size) size *= 2;
        data.resize(size * 2); // Use resize instead of assign for better performance
    }

    void add(int i, int x) {
        for (int j = size + i; j; j /= 2)
            data[j] += x;
    }

    int ith(int i) {
        int j = 1;
        while (j < size) {
            if (data[j * 2] > i)
                j = j * 2;
            else {
                i -= data[j * 2];
                j = j * 2 + 1;
            }
        }
        return j - size;
    }
};

int main() {
    int q, l;
    while (scanf("%d%d", &q, &l), q || l) {
        SegTree st(q);
        vi girls;
        map<int, int> m;

        for (int i = 0; i < q; ++i) {
            int qu, x;
            scanf("%d%d", &qu, &x);
            if (qu == 0) {
                st.add(girls.size(), 1);
                m[x] = girls.size();
                girls.push_back(x);
                if (st.data[1] > l) {
                    int j = st.ith(0);
                    st.add(j, -1);
                }
            } else if (qu == 1) {
                int j = st.ith(x - 1);
                st.add(j, -1);
            } else if (qu == 2) {
                int j = st.ith(x - 1);
                printf("%d\n", girls[j]);
            } else if (qu == 3) {
                int j = m[x];
                st.add(j, -1);
            }
        }
        puts("end");
    }
    return 0;
}

