        treeData.assign(treeSize * 2, 0);
    }

    void update(int index, int value) {
        index += treeSize; // Move index to leaf position
        treeData[index] += value;
        while (index > 1) { // Update the tree upwards
            index /= 2;
            treeData[index] = treeData[index * 2] + treeData[index * 2 + 1];
        }
    }

    int query(int i) {
        int j = 1;
        while (j < treeSize) {
            if (treeData[j * 2] > i)
                j = j * 2;
            else {
                i -= treeData[j * 2];
                j = j * 2 + 1;
            }
        }
        return j - treeSize;
    }
};

